document.addEventListener("DOMContentLoaded", function () {

  let lastScrollTop = 0;
  let header = document.getElementById("masthead");
  let homeHead = document.querySelector(".home-head");
  let phoneIcon = document.querySelector(".menu-phone-icon");
  let phoneContact = document.querySelector(".phone-contact");
  let hasScrolled = false;
  let primaryHeaderBar = document.querySelector(".ast-primary-header-bar");
  let mobileHeaderBar = document.querySelector(".ast-mobile-header-wrap ");

  // let isHomePage = window.location.pathname === "/";

  if (homeHead) {
    setTimeout(() => {
      homeHead.classList.add('active');
      if (primaryHeaderBar) primaryHeaderBar.style.borderBottom = "1px solid var(--ast-global-color-0)";
      if (mobileHeaderBar) mobileHeaderBar.style.borderBottom = "1px solid var(--ast-global-color-0)";
    }, 4000);
  }

  window.addEventListener("scroll", function () {

    let currentScroll =
      window.scrollY || document.documentElement.scrollTop;

    if (currentScroll > 100 && !hasScrolled) {
      header.style.top = "0";
      hasScrolled = true;
    }

    if (currentScroll > lastScrollTop) {
      header.style.top = "-115px";
    } else {
      header.style.top = "0";
    }

    lastScrollTop = currentScroll <= 0 ? 0 : currentScroll;
  });

  window.addEventListener("mousemove", function (event) {
    if (header.style.top === "-115px" && event.clientY < 100) {
      header.style.top = "0";
    }
  });

  header.addEventListener("mouseleave", function () {
    header.style.top = "-115px";
  });

  header.addEventListener("mouseenter", function () {
    header.style.top = "0";
  });

  phoneIcon.addEventListener("mouseenter", function() {
    phoneContact.classList.add('visible');
  });

  phoneIcon.addEventListener("mouseleave", function() {
    phoneContact.classList.remove('visible');
  });

});
